tinymce.PluginManager.add('corda', function(editor, url) {

    // Add a button that opens a window
    editor.ui.registry.addButton('corda', {
        text: '|--',
        tooltip: 'Inserir Corda',
        onAction: function() {

            editor.selection.setContent('<span class="corda">' + editor.selection.getContent() + '</span>');
        }
    });

    // Adds a menu item to the tools menu
    editor.ui.registry.addMenuItem('corda', {
        text: 'Inserir Corda',
        context: 'insert',
        onAction: function() {

            editor.selection.setContent('<span class="corda">' + editor.selection.getContent() + '</span>');
        }
    });


});